ឧទាហរណ៍កូដ៖
#include <iostream>
using namespace std;
int main() {
    int arr[5] = {5, 3, 1, 4, 2};
    // បង្ហាញអារេ
    cout << "អារេដើម: ";
    for (int i = 0; i < 5; i++) {
        cout << arr[i] << " ";
    }
    cout << endl;
    // តម្រៀបអារេ
    for (int i = 0; i < 5; i++) {
        for (int j = i + 1; j < 5; j++) {
            if (arr[i] > arr[j]) {
                int temp = arr[i];
                arr[i] = arr[j];
                arr[j] = temp;
            }
        }
    }
    // បង្ហាញអារេដែលបានតម្រៀប
    cout << "អារេដែលបានតម្រៀប: ";
    for (int i = 0; i < 5; i++) {
        cout << arr[i] << " ";
    }
    cout << endl;
    return 0;
}

