6.4. អនុគមន៍ដែលដំណើរការលើខ្សែអក្សរ
C++ ផ្តល់អនុគមន៍ជាច្រើនសម្
រាប់ដំណើរការលើខ្សែអក្សរ ដូចជា length(), substr(), find(), និង
replace()។
ឧទាហរណ៍កូដ៖
#include <iostream>
#include <string>
using namespace std;
int main() {
    string str = "Hello, World!";
    // ប្រ
វែងខ្
សែអក្សរ
    cout << "ប្រ
វែងខ្
សែអក្សរ: " << str.length() << endl;
    // ស្រ
ង់ចេញផ្នែកមួយនៃខ្
សែអក្សរ
    cout << "ផ្នែកខ្
សែអក្សរ: " << str.substr(7, 5) << endl;
    // ស្វែងរកអក្សរក្នុងខ្
សែអក្សរ
    cout << "ស្វែងរក 'World': " << str.find("World") << endl;
    // ជំនួសផ្នែកនៃខ្
សែអក្សរ
    str.replace(7, 5, "C++");
    cout << "ខ្
សែអក្សរដែលបានជំនួស: " << str << endl;
    return 0;
}
ការពន្យល់៖
- length() ប្រើដើម្បីីរកប្រវែងខ្សែអក្សរ។
- substr() ប្រើដើម្បីីស្រ
ង់ចេញផ្នែកមួយនៃខ្សែអក្សរ។
- find() ប្រើដើម្បីីស្
វែងរកអក្សរក្នុងខ្សែអក្សរ។
- replace() ប្រើដើម្បីីជំនួសផ្នែកនៃខ្សែអក្សរ។
