ផ្ទាល់ជាមួយអាសយដ្ឋានអង្គចងចាំំ។ កូដចង្អុលផ្ទុកអាសយដ្ឋានអង្គចងចាំំ ខណៈការយោងផ្តល់ឈ្
មោះ
ផ្សេងទៀទៀតឱ្យអថេរដែលមានស្
រាប់។ ផ្នែកនេះះគ្របដណ្តប់អំពីមូលដ្ឋាននៃកូដចង្អុល ការ
គណនាកូដចង្អុល ការយោង និងការចាត់ចែងអង្គចងចាំំថាមវន្ត។
7.1. ការណែនាំំអំពីកូដចង្អុល
កូដចង្អុលគឺជាអថេរដែលផ្ទុកអាសយដ្ឋានអង្គចងចាំំរបស់អថេរផ្សេង។
ឧទាហរណ៍កូដ៖
#include <iostream>
using namespace std;
int main() {
    int x = 10;
    int *ptr = &x; // កូដចង្អុល ptr ផ្ទុកអាសយដ្ឋានរបស់ x
    cout << "តម្លៃរបស់ x: " << x << endl;
    cout << "អាសយដ្ឋានរបស់ x: " << &x << endl;
    cout << "តម្លៃរបស់ ptr: " << ptr << endl;
    cout << "តម្លៃដែល ptr ចង្អុលទៅ: " << *ptr << endl;
    return 0;
}
ការពន្យល់៖
- x គឺជាអថេរធម្មតាដែលមានតម្លៃ 10។
- ptr គឺជាកូដចង្អុលដែលផ្ទុកអាសយដ្ឋានរបស់ x។

