សំណង់ (Constructor) គឺជាមុខងារពិសេសដែលត្រូូវបានហៅដោយស្វ័័យប្រវត្តិិនៅពេលបង្កើតវត្ថុ។ ការបំផ្លាញ
(Destructor) គឺជាមុខងារដែលត្រូូវបានហៅនៅពេលវត្ថុត្រូូវបានលុប។
ឧទាហរណ៍កូដ៖
#include <iostream>
using namespace std;
class Book {
public:
    string title;
    // សំណង់
    Book(string t) {
        title = t;
        cout << "Book created: " << title << endl;
    }
    // ការបំផ្លាញ
    ~Book() {
        cout << "Book destroyed: " << title << endl;
    }
};
int main() {
    Book myBook("C++ Programming");
    return 0;
}
ការពន្យល់៖
- សំណង់ Book(string t) ចាប់ផ្តើមតម្លៃ title និងបោះពុម្ពសារ។
- ការបំផ្លាញ ~Book() ត្រូូវបានហៅនៅពេលវត្ថុត្រូូវបានលុប ហើយបោះពុម្ពសារ។
