កំហុសនេះះនឹងត្រូូវបានគ្រប់គ្រងដោយ catch block ហើយបង្ហាញសារកំហុស។
11.2. Handling Multiple Exceptions
អ្នកអាចគ្រប់គ្រងកំហុសច្រើនប្រភេទដោយប្រើ catch blocks ច្រើន។ រាល់ catch block នឹងគ្រប់គ្រងកំហុស
ផ្សេងៗគ្នា។
ឧទាហរណ៍កូដ៖
#include <iostream>
using namespace std;
int main() {
    try {
        int x = 10;
        int y = 0;
        if (y == 0) {
            throw runtime_error("Division by zero is not allowed.");
        }
        int result = x / y;
        cout << "Result: " << result << endl;
    }
    catch (const runtime_error& e) {
        cout << "Runtime Error: " << e.what() << endl;
    }
    catch (const exception& e) {
        cout << "Standard Exception: " << e.what() << endl;
    }
    return 0;
}
